practice[2]=quiz('case2','Практикум педагога — выбор дела',`<p>Вы задумали открытки, а дети предлагают игру для младших. Что поможет принять решение?</p>${select('case2','Следующий шаг',[['a','Оставить только идею взрослого.'],['b','Сравнить потребность получателей, посильность и ресурсы обеих идей вместе с детьми.'],['c','Назвать любую идею выполненной практикой.']])}`)
