+quiz('synthesis','Формула трёх качеств',`<p>Соберите синтез «Радость за другого». Каждое качество используется один раз, в порядке формулы пособия.</p>${[1,2,3].map(n=>select('canonQuality'+n,'Качество '+n,[qualities[1],qualities[2],qualities[0],['pride','Гордость']])).join('')}`)
